/**
 * Roll initiative for all combatants and start combat
 *
 * Rolls a d6 (`crypto.randomInt(1, 7)`) for every combatant in the
 * encounter, sorts them by initiative descending, assigns `turnOrder`
 * indices (0-based), and transitions the encounter from `setup` to
 * `active`. Per ST3001 ГЛАВА 5 «Раунды, ходы и инициатива»: «Бросьте
 * по кубику за всех участников сражения… Выпавший на кубике результат —
 * значение инициативы для этого персонажа».
 *
 * **Side-effects (all atomic):**
 * 1. Encounter `status` transitions `setup → active`.
 * 2. `encounter.round` is set from 0 to 1.
 * 3. `encounter.activeCombatantId` is set to the combatant with
 * `turnOrder: 0` (highest initiative result).
 * 4. Every combatant row is updated with its `initiative` and `turnOrder`.
 *
 * **Tie-breaking (ST3001 ГЛАВА 5):** equal initiative rolls are broken
 * by re-rolling a fresh d6 for the tied combatants — «В случае ничьей
 * определите очерёдность хода случайным образом (бросьте ещё по одному
 * кубику, только на этот раз безо всяких модификаторов — у кого больше,
 * тот и ходит раньше)». The server runs at most three reroll passes to
 * keep the operation bounded; any combatants still tied after that are
 * left in stable insertion order and the GM is expected to use the
 * `PATCH /api/v1/encounters/{id}/initiative` reorder operation to set
 * a definitive order before the first turn.
 *
 * **Error codes (422):**
 * - `ENCOUNTER_INVALID_TRANSITION` — encounter is not in `setup` status.
 * Initiative roll is only valid from `setup`; if the encounter is
 * already `active` or `ended` this guard fires.
 * - `ENCOUNTER_NO_COMBATANTS` — the encounter has no combatants. Add at
 * least one via `POST /api/v1/encounters/{id}/combatants` before
 * rolling initiative.
 *
 */
export const rollInitiative = <ThrowOnError extends boolean = false>(options: Options<RollInitiativeData, ThrowOnError>) => (options.client ?? client).post<RollInitiativeResponses, RollInitiativeErrors, ThrowOnError>({
    security: [{
            in: 'cookie',
            name: 'better-auth.session_token',
            type: 'apiKey'
        }, { scheme: 'bearer', type: 'http' }],
    url: '/api/v1/encounters/{id}/initiative/roll',
    ...options
});

/**
 * Manually reorder the turn order (GM only)
 *
 * Allows the GM to rearrange the turn order without re-rolling initiative
 * dice. The request body must contain the full ordered list of every
 * combatant id in the encounter exactly once. The server reassigns
 * `turnOrder` indices (0-based) matching the array position.
 *
 * **This operation does NOT:**
 * - Re-roll initiative dice (`initiative` values remain unchanged).
 * - Change `encounter.activeCombatantId` (the combatant whose turn is
 * currently active stays active; the reorder takes effect from the
 * next turn advance).
 * - Change `encounter.round`.
 *
 * **Allowed only while `status` is `active`.** Returns 422
 * `ENCOUNTER_INVALID_STATUS` if called from `setup` (use
 * `rollInitiative` instead) or `ended`.
 *
 * **Validation error codes (422):**
 * - `ENCOUNTER_INVALID_STATUS` — encounter is not in `active` status.
 * - `INITIATIVE_INCOMPLETE` — at least one combatant id from the
 * encounter is absent from `combatantIds`.
 * - `INITIATIVE_DUPLICATE` — the same id appears two or more times
 * in `combatantIds`.
 * - `INITIATIVE_UNKNOWN_COMBATANT` — an id in `combatantIds` does not
 * belong to this encounter.
 *
 */
export const reorderInitiative = <ThrowOnError extends boolean = false>(options: Options<ReorderInitiativeData, ThrowOnError>) => (options.client ?? client).patch<ReorderInitiativeResponses, ReorderInitiativeErrors, ThrowOnError>({
    security: [{
            in: 'cookie',
            name: 'better-auth.session_token',
            type: 'apiKey'
        }, { scheme: 'bearer', type: 'http' }],
    url: '/api/v1/encounters/{id}/initiative',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Advance to the next combatant's turn
 *
 * Moves `encounter.activeCombatantId` forward by one position in the
 * turn order: `(currentIndex + 1) % combatants.length`.
 *
 * **Wrap behaviour:** when the advance moves past the last combatant
 * (index `combatants.length - 1`), the turn wraps to index 0 and
 * `encounter.round` is incremented by 1. `TurnAdvanceResult.isNewRound`
 * is `true` in that case.
 *
 * **Allowed only while `status` is `active`.** Returns 422
 * `ENCOUNTER_INVALID_STATUS` otherwise.
 *
 * **Defensive guard:** returns 422 `ENCOUNTER_INITIATIVE_NOT_ROLLED`
 * when `activeCombatantId` is null (i.e. initiative was never set,
 * which should not be reachable via normal `rollInitiative` flow but is
 * possible if a future code path bypasses that operation).
 *
 * **Error codes (422):**
 * - `ENCOUNTER_INVALID_STATUS` — encounter is not in `active` status.
 * - `ENCOUNTER_INITIATIVE_NOT_ROLLED` — `activeCombatantId` is null;
 * initiative must be rolled before turns can be advanced.
 *
 */
export const advanceTurn = <ThrowOnError extends boolean = false>(options: Options<AdvanceTurnData, ThrowOnError>) => (options.client ?? client).post<AdvanceTurnResponses, AdvanceTurnErrors, ThrowOnError>({
    security: [{
            in: 'cookie',
            name: 'better-auth.session_token',
            type: 'apiKey'
        }, { scheme: 'bearer', type: 'http' }],
    url: '/api/v1/encounters/{id}/turn/advance',
    ...options
});

/**
 * Advance the encounter to the start of the next round
 *
 * Atomically advances the encounter to the start of the next round.
 *
 * **Effects:**
 * - `encounter.round` is incremented by 1.
 * - `encounter.activeCombatantId` is reset to the first combatant in
 * `turnOrder` (the lowest `turnOrder` index).
 * - One `combat.updated` realtime event is emitted on the encounter's
 * session channel.
 *
 * **Allowed only while `status` is `active`.** Returns 422
 * `ENCOUNTER_INVALID_STATUS` otherwise.
 *
 * **Defensive guard:** returns 422 `ENCOUNTER_INITIATIVE_NOT_ROLLED`
 * when `activeCombatantId` is null (initiative was never set).
 *
 * The response `TurnAdvanceResult.isNewRound` is always `true` on
 * success — this endpoint always crosses a round boundary by definition.
 * Use `POST /api/v1/encounters/{id}/turn/advance` for within-round
 * progression.
 *
 */
export const advanceRound = <ThrowOnError extends boolean = false>(options: Options<AdvanceRoundData, ThrowOnError>) => (options.client ?? client).post<AdvanceRoundResponses, AdvanceRoundErrors, ThrowOnError>({
    security: [{
            in: 'cookie',
            name: 'better-auth.session_token',
            type: 'apiKey'
        }, { scheme: 'bearer', type: 'http' }],
    url: '/api/v1/encounters/{id}/round/advance',
    ...options
});

/**
 * Create a share link for a character
 *
 * Creates a new share link for the authenticated user's character. The
 * link is identified by a 24-character unguessable slug. Multiple links
 * per character are allowed — useful for different audiences or different
 * `includeGmNotes` settings.
 *
 * The optional `label` (1–80 characters) helps the owner distinguish links.
 * The optional `expiresAt` is an ISO-8601 instant; omit (or set to null)
 * for a permanent link. The optional `includeGmNotes` flag (default false)
 * controls whether the top-level `notes` field is included in the public
 * character read.
 *
 */
export const createShareLink = <ThrowOnError extends boolean = false>(options: Options<CreateShareLinkData, ThrowOnError>) => (options.client ?? client).post<CreateShareLinkResponses, CreateShareLinkErrors, ThrowOnError>({
    security: [{
            in: 'cookie',
            name: 'better-auth.session_token',
            type: 'apiKey'
        }, { scheme: 'bearer', type: 'http' }],
    url: '/api/v1/characters/{id}/share',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * List share links for a character
 *
 * Returns all non-revoked share links for the authenticated user's
 * character, ordered newest-first. Revoked links are excluded by default.
 * A `?includeRevoked` query parameter may be added in a future version.
 *
 */
export const listShareLinks = <ThrowOnError extends boolean = false>(options: Options<ListShareLinksData, ThrowOnError>) => (options.client ?? client).get<ListShareLinksResponses, ListShareLinksErrors, ThrowOnError>({
    security: [{
            in: 'cookie',
            name: 'better-auth.session_token',
            type: 'apiKey'
        }, { scheme: 'bearer', type: 'http' }],
    url: '/api/v1/characters/{id}/shares',
    ...options
});

/**
 * Revoke a share link
 *
 * Soft-revokes a share link by setting its `revokedAt` timestamp. After
 * revocation, `GET /api/v1/public/character/{slug}` returns 410 Gone.
 * The link row is not deleted — historical view counts are preserved.
 * The caller must own the character the link belongs to.
 *
 */
export const revokeShareLink = <ThrowOnError extends boolean = false>(options: Options<RevokeShareLinkData, ThrowOnError>) => (options.client ?? client).delete<RevokeShareLinkResponses, RevokeShareLinkErrors, ThrowOnError>({
    security: [{
            in: 'cookie',
            name: 'better-auth.session_token',
            type: 'apiKey'
        }, { scheme: 'bearer', type: 'http' }],
    url: '/api/v1/share-links/{id}',
    ...options
});

/**
 * Get a publicly-shared character by slug
 *
 * Returns the character associated with the given share-link slug.
 * No authentication is required.
 *
 * The `notes` field (top-level GM notes) is included only when the share
 * link was created with `includeGmNotes: true`. If the link does not
 * include GM notes, `notes` is always returned as `null` regardless of
 * whether the character actually has notes.
 *
 * Error semantics:
 * - `404` — slug does not exist or was never created.
 * - `410` — slug existed but has been revoked or has expired.
 *
 */
export const getPublicCharacter = <ThrowOnError extends boolean = false>(options: Options<GetPublicCharacterData, ThrowOnError>) => (options.client ?? client).get<GetPublicCharacterResponses, GetPublicCharacterErrors, ThrowOnError>({ url: '/api/v1/public/character/{slug}', ...options });

/**
 * OG image for a shared character (Feature 6.3 — not yet implemented)
 *
 * Returns a PNG Open Graph image for the shared character. Intended for
 * social-media preview unfurling.
 *
 * **This endpoint is not yet implemented.** It will always return 501
 * until Feature 6.3 lands the server-side renderer. Consumers should plan
 * for the following cache headers on the eventual 200 response:
 * `Cache-Control: public, max-age=3600, stale-while-revalidate=86400`.
 *
 */
export const getCharacterOgImage = <ThrowOnError extends boolean = false>(options: Options<GetCharacterOgImageData, ThrowOnError>) => (options.client ?? client).get<GetCharacterOgImageResponses, GetCharacterOgImageErrors, ThrowOnError>({ url: '/api/v1/public/og/character/{slug}.png', ...options });

/**
 * List roll history for a character
 *
 * Returns the most recent rolls for the character, ordered newest-first.
 * Default limit is 50; maximum is 100.
 *
 */
export const listRolls = <ThrowOnError extends boolean = false>(options: Options<ListRollsData, ThrowOnError>) => (options.client ?? client).get<ListRollsResponses, ListRollsErrors, ThrowOnError>({
    security: [{
            in: 'cookie',
            name: 'better-auth.session_token',
            type: 'apiKey'
        }, { scheme: 'bearer', type: 'http' }],
    url: '/api/v1/characters/{id}/rolls',
    ...options
});

/**
 * Roll dice for a character
 *
 * Rolls `pool` d6 server-side using a cryptographically secure RNG.
 * Hits are counted as the number of 6s. The caller provides a human-readable
 * `label` (e.g. "Pilot · Evade") and an optional `gameSessionId` (reserved for
 * Feature 7.2 — pass null until GameSession lands).
 *
 * Pool is clamped by the server from the submitted value. Condition penalties
 * must be pre-applied by the caller before sending `pool`; the server does not
 * re-apply them from character state.
 *
 * When an optional `breakdown` object is supplied alongside `pool`, the server
 * validates that `attribute + skill + gear + modifier + helpers === pool`; a
 * mismatch is rejected with HTTP 400 `ROLL_BREAKDOWN_MISMATCH`. Programmatic
 * callers (internal command handlers, dice engine) can omit `breakdown` entirely.
 *
 */
export const createRoll = <ThrowOnError extends boolean = false>(options: Options<CreateRollData, ThrowOnError>) => (options.client ?? client).post<CreateRollResponses, CreateRollErrors, ThrowOnError>({
    security: [{
            in: 'cookie',
            name: 'better-auth.session_token',
            type: 'apiKey'
        }, { scheme: 'bearer', type: 'http' }],
    url: '/api/v1/characters/{id}/rolls',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Push (reroll) a roll
 *
 * Rerolls all non-6 dice exactly once. After a push the roll cannot be
 * pushed again (`pushed` becomes `true`). Returns 400 with code
 * `PUSH_NOT_ALLOWED_ON_NON_SKILL_ROLL` if the roll's `kind` is not
 * `skill` (ST3001 ГЛАВА 3 §«Вознесение молитв»). Returns 422 with code
 * `ROLL_NOT_PUSHABLE` if:
 * - The roll has already been pushed.
 * - The owning character has the Exhausted condition (PRD §10).
 *
 */
export const pushRoll = <ThrowOnError extends boolean = false>(options: Options<PushRollData, ThrowOnError>) => (options.client ?? client).patch<PushRollResponses, PushRollErrors, ThrowOnError>({
    security: [{
            in: 'cookie',
            name: 'better-auth.session_token',
            type: 'apiKey'
        }, { scheme: 'bearer', type: 'http' }],
    url: '/api/v1/rolls/{id}/push',
    ...options
});
